-- Somente leitura. Esperado: RLS true em todas as tabelas e permissões privilegiadas false.
-- Não altera papéis, políticas, dados ou contas.
select (select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('profiles','places','reviews','photos','favorites','moderation_items','moderation_actions','safe_admins','notifications','place_messages','safe_write_events')) as protected_tables,
jsonb_build_object('self_approve_place',has_column_privilege('authenticated','public.places','verification_status','UPDATE'),'edit_photo_owner',has_column_privilege('authenticated','public.photos','owner_id','UPDATE'),'self_approve_profile',has_column_privilege('authenticated','public.profiles','moderation_state','UPDATE'),'grant_moderator',has_table_privilege('authenticated','public.safe_admins','INSERT'),'erase_budget',has_table_privilege('authenticated','public.safe_write_events','DELETE'),'anon_moderate',has_function_privilege('anon','public.moderate_content(uuid,text,text)','EXECUTE'),'client_provider_verdict',has_function_privilege('authenticated','public.safe_apply(uuid,text,text,text,jsonb)','EXECUTE')) as privileged_client_permissions;
